#!/usr/bin/env node
/**
 * Read-only audit of one or more explicitly named recitation audio files.
 * Detects likely silent padding inside the SOURCE recording, not just padding
 * generated by Remotion. No automatic trimming (protect sacred recitation).
 */
import { spawnSync } from "node:child_process";
import { statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const positive = (v) => Number.isFinite(v) && v >= 0;
export const parseSilenceEvents = (log) => {
  const segments = [];
  let start = null;
  for (const line of log.split(/\r?\n/)) {
    const began = line.match(/silence_start:\s*([0-9.]+)/);
    if (began) start = Number(began[1]);
    const ended = line.match(/silence_end:\s*([0-9.]+)/);
    if (ended && start !== null) {
      const end = Number(ended[1]);
      if (positive(start) && positive(end) && end >= start) segments.push({ start, end });
      start = null;
    }
  }
  return { segments, ongoingStart: positive(start) ? start : null };
};
export const findSilentEdges = (log, duration) => {
  if (!Number.isFinite(duration) || duration <= 0) throw new Error("Invalid audio duration");
  const { segments, ongoingStart } = parseSilenceEvents(log);
  const normalized = ongoingStart !== null
    ? [...segments, { start: ongoingStart, end: duration }]
    : segments;
  const lead = normalized.find(({ start }) => start <= 0.025);
  const trail = [...normalized].reverse().find(({ end }) => end >= duration - 0.035);
  // ffmpeg reports decimal timestamps; round durations to milliseconds so
  // 4.000 - 3.770 is exposed as 0.230, never 0.22999999999999998.
  const seconds = (value) => Math.round(Math.min(duration, Math.max(0, value)) * 1000) / 1000;
  return {
    leadingSec: lead ? seconds(lead.end) : 0,
    trailingSec: trail ? seconds(duration - trail.start) : 0,
    middlePauses: normalized.filter(({ start, end }) => start > 0.025 && end < duration - 0.035).length,
  };
};
const run = (command, args) => {
  const r = spawnSync(command, args, {
    encoding: "utf8", timeout: 90000, maxBuffer: 5 * 1024 * 1024,
    stdio: ["ignore", "pipe", "pipe"],
  });
  if (r.error || r.status !== 0) throw new Error(`${command} failed: ${r.error?.message || r.stderr?.slice(-400) || r.status}`);
  return r;
};
export const auditAudioFile = (file, warningSec = 0.18) => {
  const name = path.resolve(file);
  if (!/\.(mp3|m4a|wav|ogg|flac)$/i.test(name) || !statSync(name).isFile())
    throw new Error("Choose an existing supported audio file explicitly.");
  const duration = Number(run("ffprobe", [
    "-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", name,
  ]).stdout.trim());
  if (!Number.isFinite(duration) || duration <= 0) throw new Error("Cannot measure audio duration");
  const detect = run("ffmpeg", ["-nostdin", "-hide_banner", "-nostats", "-i", name,
    "-af", "silencedetect=noise=-38dB:d=0.08", "-f", "null", "-"]);
  const edges = findSilentEdges(detect.stderr, duration);
  return { file: name, durationSec: duration, ...edges,
    potentialPadding: edges.leadingSec >= warningSec || edges.trailingSec >= warningSec };
};
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (!args.length || args.some((x) => x.startsWith("--"))) {
    console.error("Usage: node scripts/studio-recitation-silence.mjs /ABSOLUTE/RECITATION.mp3 [more-files...]");
    process.exitCode = 2;
  } else {
    let failures = 0;
    for (const name of args) {
      try {
        const result = auditAudioFile(name);
        console.log(JSON.stringify(result));
        if (result.potentialPadding) console.log("WARN: possible source MP3 silence; inspect first and last audible phoneme at 1x. DO NOT auto-trim Quran.");
      } catch (e) {
        failures++;
        console.error(`AUDIT_ERROR ${name}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
    if (failures) process.exitCode = 1;
  }
}
